import{_ as i,o as e,c as t,a4 as s}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"Multi-Region 部署","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/scale/multi-region.md","filePath":"system-design/scale/multi-region.md","lastUpdated":1788475713000}'),n={name:"system-design/scale/multi-region.md"};function l(o,a,r,c,h,d){return e(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="multi-region-部署" tabindex="-1">Multi-Region 部署 <a class="header-anchor" href="#multi-region-部署" aria-label="Permalink to &quot;Multi-Region 部署&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Multi-region = 让服务在<strong>多个地理区域</strong>运行, 目的:</p><ol><li><strong>Lower latency</strong>: 同区域用户 &lt; 5ms RTT (vs 跨洋 100-300ms)</li><li><strong>Disaster Recovery</strong>: 一区全毁, 另一区扛</li><li><strong>Data residency</strong>: 数据合规 (GDPR: EU 用户 数据在 欧盟)</li></ol><p>但代价: data replication latency higher, consistency 降级, cost 增加 1.5-2×。本章梳理 multi-region architecture patterns, trade-off (latency vs consistency vs cost), 典型实现 (CockroachDB multi-reg, DynamoDB Global Table, Spinaker Active-Passive vs Active-Active, CDN + DNS routing)。</p><hr><h2 id="一、core-pattern" tabindex="-1">一、Core Pattern <a class="header-anchor" href="#一、core-pattern" aria-label="Permalink to &quot;一、Core Pattern&quot;">​</a></h2><h3 id="active-passive-冷战" tabindex="-1">Active-Passive (冷战) <a class="header-anchor" href="#active-passive-冷战" aria-label="Permalink to &quot;Active-Passive (冷战)&quot;">​</a></h3><ul><li>活跃在 one region, hot failover 到 standby on other.</li><li>数据从 active → passive sync replication (async); RPO &gt; 0.</li><li>failover time 5-60 minutes (DNS change).</li><li>成本 1 replica cost.</li></ul><h3 id="active-active-热站" tabindex="-1">Active-Active (热站) <a class="header-anchor" href="#active-active-热站" aria-label="Permalink to &quot;Active-Active (热站)&quot;">​</a></h3><ul><li>多 region 同时 accept writes.</li><li>Multi-master replication 双写同步。</li><li>Conflict resolution: LWW (timestamp), vector clock, or merge function.</li><li>latency ~ local区域 &lt;5ms, cross region ~100ms multi write.</li></ul><h3 id="read-replica-global" tabindex="-1">Read-Replica global <a class="header-anchor" href="#read-replica-global" aria-label="Permalink to &quot;Read-Replica global&quot;">​</a></h3><ul><li>写 在 single primary region, 各地只读 (RPO=0 for writes within primary region).</li><li>延迟: local (primary region &lt;5ms write) + cross-region reads locally fast (~200ms behind).</li><li>适合 read-heavier landscape (content, social feeds).</li></ul><hr><h2 id="二、cdn-dns-based-routing" tabindex="-1">二、CDN + DNS based Routing <a class="header-anchor" href="#二、cdn-dns-based-routing" aria-label="Permalink to &quot;二、CDN + DNS based Routing&quot;">​</a></h2><h3 id="route53-latency-based-routing" tabindex="-1">Route53 Latency-based Routing <a class="header-anchor" href="#route53-latency-based-routing" aria-label="Permalink to &quot;Route53 Latency-based Routing&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User → DNS request</span></span>
<span class="line"><span>Route53 → 根据 user latency choose nearest healthy region IP</span></span>
<span class="line"><span>CDN (CloudFront / Cloudflare) cache fronting.</span></span></code></pre></div><ul><li>DNS 基于 延迟路由, 不要 user pick.</li><li>高 failover: TTL 60s, health check DNS → switch user.</li><li>CDN serve static content, dynamic path origin 回到 region.</li></ul><h3 id="global-load-balancer-anycast-ip" tabindex="-1">Global Load Balancer (anycast IP) <a class="header-anchor" href="#global-load-balancer-anycast-ip" aria-label="Permalink to &quot;Global Load Balancer (anycast IP)&quot;">​</a></h3><p>Google Cloud anycast IP 一个 IP 全球 consistent, data 同 region 分发: 任何请求 route 到 nearest backend. AWS Global Accelerator 提供 similar.</p><h3 id="application-consistency" tabindex="-1">Application Consistency <a class="header-anchor" href="#application-consistency" aria-label="Permalink to &quot;Application Consistency&quot;">​</a></h3><p>同一 user&#39;s <strong>session</strong> 可能 sticky to one region via cookie. 若 region 崩, session 迁移其他。</p><hr><h2 id="三、data-geo-partitioned" tabindex="-1">三、Data geo-partitioned <a class="header-anchor" href="#三、data-geo-partitioned" aria-label="Permalink to &quot;三、Data geo-partitioned&quot;">​</a></h2><h3 id="shard-by-region" tabindex="-1">Shard by Region <a class="header-anchor" href="#shard-by-region" aria-label="Permalink to &quot;Shard by Region&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user_id → region hash.</span></span>
<span class="line"><span>table REGIONAL BY ROW in CockroachDB: userid → us-east region.</span></span></code></pre></div><h3 id="cross-region-global-tables" tabindex="-1">Cross-region global tables <a class="header-anchor" href="#cross-region-global-tables" aria-label="Permalink to &quot;Cross-region global tables&quot;">​</a></h3><p>某些表 global (e.g., legal terms, universal catalog). replicas 全球, cross-region 写 重 过多个 区域, weak consistency.</p><h3 id="cockroachdb-multi-region-sql" tabindex="-1">CockroachDB Multi-region SQL <a class="header-anchor" href="#cockroachdb-multi-region-sql" aria-label="Permalink to &quot;CockroachDB Multi-region SQL&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mydb </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PRIMARY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> REGION </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;us-east1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mydb </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> REGION </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;us-west1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mydb </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> REGION </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eu-west1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LOCALITY REGIONAL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ROW</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- each row belong to chosen region</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> catalog</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LOCALITY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GLOBAL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- replicated to all regions</span></span></code></pre></div><p>CockroachDB 使用 HLC, multi-region 读 有限 延迟.</p><h3 id="spanner-multi-region" tabindex="-1">Spanner Multi-region <a class="header-anchor" href="#spanner-multi-region" aria-label="Permalink to &quot;Spanner Multi-region&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CREATE TABLE Users (...) PRIMARY KEY (UserId),</span></span>
<span class="line"><span>  INTERLEAVE IN PARENT ...;</span></span>
<span class="line"><span>-- Configure replication across us-east1,us-west1, europe-west9</span></span></code></pre></div><p>Spanner TrueTime 保证 external consistency across regions.</p><hr><h2 id="四、data-residency-gdpr" tabindex="-1">四、Data Residency (GDPR) <a class="header-anchor" href="#四、data-residency-gdpr" aria-label="Permalink to &quot;四、Data Residency (GDPR)&quot;">​</a></h2><p>用户 地域 数据必须留在同区域:</p><ul><li>EU 用户 数据 必 EU 区 replica。</li><li>法律 metric 靠 region-sharding forced local table replicas only allowed.</li></ul><p>Multi-region 可能涉及 cross-region commit queue, data protection by region local dataset.</p><hr><h2 id="五、consistency-in-multi-region" tabindex="-1">五、Consistency in Multi-Region <a class="header-anchor" href="#五、consistency-in-multi-region" aria-label="Permalink to &quot;五、Consistency in Multi-Region&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>技术</th><th>Latency</th><th>Cost</th></tr></thead><tbody><tr><td>Strong consistency (linearizability)</td><td>Paxos/Raft cross-DC with commit-wait (TrueTime)</td><td>100-200ms per write</td><td>高 (全球多数派 ack)</td></tr><tr><td>Causal consistency</td><td>HLC / Vector Clock, cross region read replicas</td><td>10-200ms 写本地, read ≤ 1s lag</td><td>中</td></tr><tr><td>Eventual consistency</td><td>Async replication + &lt; 1s read latency possible</td><td>&lt;5ms local writes, cross-region 读 几百 ms 以上 update</td><td>低</td></tr></tbody></table><p>Multi-region 强一 需 majority 跨 DC 复制 → latency cross DC 至少 50-150ms.</p><hr><h2 id="六、case-studies" tabindex="-1">六、Case Studies <a class="header-anchor" href="#六、case-studies" aria-label="Permalink to &quot;六、Case Studies&quot;">​</a></h2><h3 id="netflix-active-active-multi-region" tabindex="-1">Netflix Active-Active Multi-Region <a class="header-anchor" href="#netflix-active-active-multi-region" aria-label="Permalink to &quot;Netflix Active-Active Multi-Region&quot;">​</a></h3><p>Netflix 三 AWS region (us-east-1, us-west-2, eu-west-1). 采用 multi-region active-active with <strong>ultra-strong event-based</strong> CDC sync + CDN + always routed DNS/anycast.</p><p>业务 使用 stale 容忍读 (轻微 delay user profile won&#39;t break UX).</p><h3 id="google-spanner-multi-region" tabindex="-1">Google Spanner Multi-Region <a class="header-anchor" href="#google-spanner-multi-region" aria-label="Permalink to &quot;Google Spanner Multi-Region&quot;">​</a></h3><p>Google Ads 系统 跨 continent 数据 true external consistency TrueTime—— commit-wait ~14ms 两 DC roundtrip guarantee. Costs higher but worth billions revenue ads.</p><h3 id="cockroachdb-by-cloud-company-to-europe" tabindex="-1">CockroachDB by Cloud Company to Europe <a class="header-anchor" href="#cockroachdb-by-cloud-company-to-europe" aria-label="Permalink to &quot;CockroachDB by Cloud Company to Europe&quot;">​</a></h3><p>某金融服务公司 用 CockroachDB multi-region cluster <code>us-east-1</code> + <code>eu-central-1</code>, 分区化的 user 数据 (region by row). Cross region user data 不能 legal cross-region move.</p><hr><h2 id="七、multi-region-failover-mechanics" tabindex="-1">七、Multi-Region Failover Mechanics <a class="header-anchor" href="#七、multi-region-failover-mechanics" aria-label="Permalink to &quot;七、Multi-Region Failover Mechanics&quot;">​</a></h2><h3 id="active-passive-failover" tabindex="-1">Active-Passive Failover <a class="header-anchor" href="#active-passive-failover" aria-label="Permalink to &quot;Active-Passive Failover&quot;">​</a></h3><ul><li>Health check 持续: DNS 停止 active region.</li><li>异步 replication sync 保证 RPO min (5s to 0s replay).</li><li>Traffic migration = route switch DNS / BGP → replay underway.</li></ul><h3 id="active-active-failover" tabindex="-1">Active-Active Failover <a class="header-anchor" href="#active-active-failover" aria-label="Permalink to &quot;Active-Active Failover&quot;">​</a></h3><p>Remove 故障 region from routing — 其他 区域 自动承担 all traffic. 无需 failover 过程。</p><h3 id="disaster-recovery-planning" tabindex="-1">Disaster Recovery planning <a class="header-anchor" href="#disaster-recovery-planning" aria-label="Permalink to &quot;Disaster Recovery planning&quot;">​</a></h3><p>Periodic DR test: Chaos engineering Netflix Simian Army random kill regions, read verify others pick up.</p><hr><h2 id="八、典型事故" tabindex="-1">八、典型事故 <a class="header-anchor" href="#八、典型事故" aria-label="Permalink to &quot;八、典型事故&quot;">​</a></h2><h3 id="aws-us-east-1-regional-outage-feb-2017" tabindex="-1">AWS us-east-1 regional outage Feb 2017 <a class="header-anchor" href="#aws-us-east-1-regional-outage-feb-2017" aria-label="Permalink to &quot;AWS us-east-1 regional outage Feb 2017&quot;">​</a></h3><p>某 S3 区域损 几小时服, 多于 netflix 用 multi-region 避免 但广大依赖 区 services 遭受 二 接 down。</p><h3 id="apple-icloud-multi-region-2015" tabindex="-1">Apple iCloud multi-region 2015 <a class="header-anchor" href="#apple-icloud-multi-region-2015" aria-label="Permalink to &quot;Apple iCloud multi-region 2015&quot;">​</a></h3><p>iCloud 服务 outage 于 multi-region replication sync loop, bug 导致 数据 replication 环 直 塞 满 网络, 需 全 shut off.</p><h3 id="spotify-eu-region-outage" tabindex="-1">Spotify EU region outage <a class="header-anchor" href="#spotify-eu-region-outage" aria-label="Permalink to &quot;Spotify EU region outage&quot;">​</a></h3><p>Spotify 欧 区 改 DNS failover wrong → unintended burst US-East cluster → impact US users; failback 触 跳 multi-region capacity overflow.</p><hr><h2 id="九、易错清单" tabindex="-1">九、易错清单 <a class="header-anchor" href="#九、易错清单" aria-label="Permalink to &quot;九、易错清单&quot;">​</a></h2><ol><li><strong>Strong consistency cross-region: 50-200ms latency unavoidable</strong> — accept for true consistency pay latency tax.</li><li><strong>Async replication RPO &gt; 0 须 明确 SLA</strong>: tell business acceptable data loss.</li><li><strong>Data residency compliance = region shard 不能 cross-region replicated</strong>: legal advice before deployment advice.</li><li><strong>DNS failover TTL default &gt; 60s</strong> means stale routing post-failover; minimize TTL with active health checks.</li><li><strong>Active-Active conflict resolution: key not model</strong>: LWW conflict resolution bias; must design per entity.</li></ol><hr><h2 id="十、这一章带走的东西" tabindex="-1">十、这一章带走的东西 <a class="header-anchor" href="#十、这一章带走的东西" aria-label="Permalink to &quot;十、这一章带走的东西&quot;">​</a></h2><ol><li>Active-Passive (standby) vs Active-Active (accept writes in all) vs Read-Replica multi-reg.</li><li>Data geo-partitioning: REGIONAL BY ROW / GLOBAL 表 in CockroachDB + Spanner.</li><li>Consistency spectrum: strong (Paxos cross-DC, 100ms) → causal (HLC) → eventual (async &lt;1s).</li><li>CDN + DNS latency routing 解决 read, write 走向 origin region.</li><li>Multi-region DR: active health check + DNS + failover 测试.</li></ol><hr><p>下一节 → <a href="./resilience">Resilience Patterns</a></p>`,76)])])}const g=i(n,[["render",l]]);export{u as __pageData,g as default};
